INSERT INTO stimuli (id,stimulus_type,title,content,asset_url,transcript,audio_duration_seconds,year_level,domain,status,created_by) VALUES ('a3dff03e-972d-5e97-b7fb-4b3a033a6f53','TEXT','The Creek Sound Map','Arun liked helping at the creek reserve, especially when there was a small job that nobody had planned. One Thursday, Arun noticed the sound map was not working as expected. The problem seemed simple at first, but the usual quick fix did not help. Arun decided to stop and look carefully instead of rushing.
