INSERT INTO stimuli (id,stimulus_type,title,content,asset_url,transcript,audio_duration_seconds,year_level,domain,status,created_by) VALUES ('0e81cc71-59dc-5e35-9ef2-1f7ec0057dac','TEXT','The Windy Sculpture','Noah liked helping at the community hall, especially when there was a small job that nobody had planned. One Tuesday, Noah noticed the reed sculpture was not working as expected. The problem seemed simple at first, but the usual quick fix did not help. Noah decided to stop and look carefully instead of rushing.
INSERT INTO stimuli (id,stimulus_type,title,content,asset_url,transcript,audio_duration_seconds,year_level,domain,status,created_by) VALUES ('aec4c9fd-dcfa-59dc-99b6-89887218adcf','TEXT','A Lantern for the Jetty — A Different Day','Ruby liked helping at the sea fog, especially when there was a small job that nobody had planned. One Thursday, Ruby noticed the jetty lantern was not working as expected. The problem seemed simple at first, but the usual quick fix did not help. Ruby decided to stop and look carefully instead of rushing.
