INSERT INTO stimuli (id,stimulus_type,title,content,asset_url,transcript,audio_duration_seconds,year_level,domain,status,created_by) VALUES ('b7b0953f-5931-5946-b8ea-9fccc163419b','TEXT','A Lantern for the Jetty','Ruby liked helping at the sea fog, especially when there was a small job that nobody had planned. One Friday, Ruby noticed the jetty lantern was not working as expected. The problem seemed simple at first, but the usual quick fix did not help. Ruby decided to stop and look carefully instead of rushing.
INSERT INTO stimuli (id,stimulus_type,title,content,asset_url,transcript,audio_duration_seconds,year_level,domain,status,created_by) VALUES ('4d5c6d65-4fee-5c87-be92-29fbca5f3858','TEXT','The Seed Library — A Different Day','Luca liked helping at the community garden, especially when there was a small job that nobody had planned. One Tuesday, Luca noticed the seed envelopes was not working as expected. The problem seemed simple at first, but the usual quick fix did not help. Luca decided to stop and look carefully instead of rushing.
