INSERT INTO stimuli (id,stimulus_type,title,content,asset_url,transcript,audio_duration_seconds,year_level,domain,status,created_by) VALUES ('edf16fed-cb6e-5ab7-8243-559b16c35caf','TEXT','The Seed Library','Luca liked helping at the community garden, especially when there was a small job that nobody had planned. One Tuesday, Luca noticed the seed envelopes was not working as expected. The problem seemed simple at first, but the usual quick fix did not help. Luca decided to stop and look carefully instead of rushing.
