INSERT INTO stimuli (id,stimulus_type,title,content,asset_url,transcript,audio_duration_seconds,year_level,domain,status,created_by) VALUES ('21b91931-366a-5689-8558-55e128fee719','TEXT','The Night Garden List','Amara liked helping at the backyard habitat, especially when there was a small job that nobody had planned. One Tuesday, Amara noticed the garden list was not working as expected. The problem seemed simple at first, but the usual quick fix did not help. Amara decided to stop and look carefully instead of rushing.
INSERT INTO stimuli (id,stimulus_type,title,content,asset_url,transcript,audio_duration_seconds,year_level,domain,status,created_by) VALUES ('44361a42-05f2-5571-a1f2-2ef2df588d4f','TEXT','The Museum Window — A Different Day','Kai liked helping at the local museum, especially when there was a small job that nobody had planned. One Friday, Kai noticed the old window frame was not working as expected. The problem seemed simple at first, but the usual quick fix did not help. Kai decided to stop and look carefully instead of rushing.
